<?php
$root=dirname(__DIR__);$lock=$root.'/storage/install.lock';$configFile=$root.'/config/config.php';
if(is_file($lock)||is_file($configFile)){http_response_code(403);echo '<h1>Installer locked</h1><p>Existing Platform configuration detected. Use the protected administration tools, not the installer.</p>';exit;}
require_once $root.'/app/Core/Uuid.php';use Digiti\Core\Uuid;
$errors=[];$success=false;$requirements=[
 'PHP >= 8.2'=>version_compare(PHP_VERSION,'8.2.0','>='),
 'PDO MySQL'=>extension_loaded('pdo_mysql'),
 'OpenSSL'=>extension_loaded('openssl'),
 'cURL'=>extension_loaded('curl'),
 'Redis extension'=>class_exists('Redis'),
 'JSON'=>extension_loaded('json'),
 'Storage writable'=>is_writable($root.'/storage'),
];
if($_SERVER['REQUEST_METHOD']==='POST'){
  $db=['host'=>trim($_POST['db_host']??'127.0.0.1'),'port'=>(int)($_POST['db_port']??3306),'name'=>trim($_POST['db_name']??''),'user'=>trim($_POST['db_user']??''),'pass'=>(string)($_POST['db_pass']??'')];
  $appUrl=rtrim(trim($_POST['app_url']??'https://platform.digiti.in'),'/');$authUrl=rtrim(trim($_POST['auth_url']??'https://auth.digiti.in'),'/');$domainsTarget=strtolower(trim($_POST['domains_target']??'domains.digiti.in'));$epaperUrl=rtrim(trim($_POST['epaper_url']??'https://epaper.digiti.in'),'/');$epaperCallback=rtrim(trim($_POST['epaper_callback']??'https://epaper.digiti.in/auth/callback'),'/');
  $adminEmail=strtolower(trim($_POST['admin_email']??''));$adminName=trim($_POST['admin_name']??'Platform Administrator');$adminPass=(string)($_POST['admin_pass']??'');
  if(!$db['name']||!$db['user'])$errors[]='Database name and user are required.';if(!filter_var($adminEmail,FILTER_VALIDATE_EMAIL))$errors[]='Valid administrator email required.';if(strlen($adminPass)<12)$errors[]='Administrator password must be at least 12 characters.';if(($_POST['confirm_new_database']??'')!=='NEW EMPTY DATABASE')$errors[]='Confirm that this is a new empty database before installing.';
  foreach($requirements as$n=>$ok)if(!$ok)$errors[]='Requirement failed: '.$n;
  if(!$errors){
    try{
      $dsn="mysql:host={$db['host']};port={$db['port']};dbname={$db['name']};charset=utf8mb4";$pdo=new PDO($dsn,$db['user'],$db['pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);
      $probe=$pdo->prepare('SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=? AND table_name IN ("platform_admins","products","applications","domains","invoices","audit_events")');
      $probe->execute([$db['name']]);
      if((int)$probe->fetchColumn()>0)throw new RuntimeException('This database already contains Platform tables. Installation is blocked to protect existing products, tenants, billing and audit history. Use a new empty database.');
      $schema=file_get_contents($root.'/database/schema.sql');foreach(array_filter(array_map('trim',preg_split('/;\s*(?:\r?\n|$)/',$schema)))as$sql)$pdo->exec($sql);
      $appKey=bin2hex(random_bytes(32));$updateKey=bin2hex(random_bytes(24));
      $redisEnabled=!empty($_POST['redis_enabled']);$redis=['enabled'=>$redisEnabled,'host'=>trim($_POST['redis_host']??'127.0.0.1'),'port'=>(int)($_POST['redis_port']??6379),'username'=>trim($_POST['redis_username']??'')?:null,'password'=>(string)($_POST['redis_password']??'')?:null,'database'=>(int)($_POST['redis_database']??0),'prefix'=>'digiti:prod:platform:'];
      if($redisEnabled&&class_exists('Redis')){$r=new Redis();$r->connect($redis['host'],$redis['port'],1.5);if($redis['password'])$r->auth($redis['username']?[$redis['username'],$redis['password']]:$redis['password']);$r->select($redis['database']);$r->ping();}
      $cfg=['app'=>['name'=>'Digiti Platform','env'=>$_POST['env']??'production','url'=>$appUrl,'auth_url'=>$authUrl,'domains_target'=>$domainsTarget,'key'=>$appKey,'update_key'=>$updateKey,'timezone'=>$_POST['timezone']??'Asia/Kolkata'],'db'=>$db+['charset'=>'utf8mb4'],'redis'=>$redis,'mail'=>['from'=>$_POST['mail_from']??'no-reply@digiti.in'],'billing'=>['default_provider'=>'manual','razorpay_key_id'=>'','razorpay_key_secret'=>'','razorpay_webhook_secret'=>'','stripe_secret'=>'','stripe_webhook_secret'=>''],'edge'=>['provider'=>'manual','cloudflare_api_token'=>'','cloudflare_zone_id'=>'']];
      // Write private application config only after the new database has been initialized successfully.
      $pdo->beginTransaction();
      $adminGuid=Uuid::v7();$st=$pdo->prepare('INSERT INTO platform_admins(admin_guid,email,display_name,password_hash,role_key,status,created_at,updated_at) VALUES(?,?,?,?,"SUPER_ADMIN","ACTIVE",NOW(6),NOW(6)) ON DUPLICATE KEY UPDATE display_name=VALUES(display_name),password_hash=VALUES(password_hash),updated_at=NOW(6)');$st->execute([Uuid::toBinary($adminGuid),$adminEmail,$adminName,password_hash($adminPass,PASSWORD_DEFAULT)]);
      $productGuid=Uuid::v7();$st=$pdo->prepare('INSERT INTO products(product_guid,product_key,name,status,description,created_at,updated_at) VALUES(?,"EPAPER","ePaper SaaS","ACTIVE","Multi-tenant digital newspaper and ePaper SaaS platform",NOW(6),NOW(6)) ON DUPLICATE KEY UPDATE name=VALUES(name),status="ACTIVE",updated_at=NOW(6)');$st->execute([Uuid::toBinary($productGuid)]);$row=$pdo->query('SELECT product_guid FROM products WHERE product_key="EPAPER"')->fetch(PDO::FETCH_ASSOC);$productBin=$row['product_guid'];
      $oauthClient='epaper_'.bin2hex(random_bytes(10));$appGuid=Uuid::v7();$appSt=$pdo->prepare('INSERT INTO applications(application_guid,product_guid,application_key,name,base_url,admin_url,health_url,callback_url,oauth_client_id,integration_mode,status,created_at,updated_at) VALUES(?, ?,"city_epaper","ePaper SaaS",?,?,?, ?,?,"REMOTE_API","ACTIVE",NOW(6),NOW(6)) ON DUPLICATE KEY UPDATE base_url=VALUES(base_url),admin_url=VALUES(admin_url),health_url=VALUES(health_url),callback_url=VALUES(callback_url),updated_at=NOW(6)');$appSt->execute([Uuid::toBinary($appGuid),$productBin,$epaperUrl,$epaperUrl.'/admin',$epaperUrl.'/health/ready',$epaperCallback,$oauthClient]);$appRow=$pdo->query('SELECT application_guid FROM applications WHERE application_key="city_epaper"')->fetch(PDO::FETCH_ASSOC);$appBin=$appRow['application_guid'];$redir=$pdo->prepare('INSERT INTO application_redirect_uris(redirect_guid,application_guid,redirect_uri,status,created_at) VALUES(?,?,?,"ACTIVE",NOW(6)) ON DUPLICATE KEY UPDATE status="ACTIVE"');$redir->execute([Uuid::toBinary(Uuid::v7()),$appBin,$epaperCallback]);
      $featureDefs=[['EPAPER.PUBLICATIONS','Publications','LIMIT'],['EPAPER.ADMIN_USERS','Admin users','LIMIT'],['EPAPER.STORAGE_GB','Storage GB','LIMIT'],['EPAPER.OCR_SEARCH','OCR Search','BOOLEAN'],['EPAPER.SMART_ARTICLE','Smart Article','BOOLEAN'],['EPAPER.CLIPPING','Clipping','BOOLEAN'],['EPAPER.OFFLINE','Offline Reading','BOOLEAN'],['EPAPER.AD_FREE','Ad Free','BOOLEAN'],['PLATFORM.CUSTOM_DOMAINS','Custom Domains','LIMIT'],['PLATFORM.API_ACCESS','API Access','BOOLEAN'],['PLATFORM.SSO','SSO','BOOLEAN']];
      $insF=$pdo->prepare('INSERT INTO features(feature_guid,product_guid,feature_key,name,feature_type,unit,created_at) VALUES(?,?,?,?,?,?,NOW(6)) ON DUPLICATE KEY UPDATE name=VALUES(name),feature_type=VALUES(feature_type)');
      foreach($featureDefs as$f)$insF->execute([Uuid::toBinary(Uuid::v7()),str_starts_with($f[0],'EPAPER.')?$productBin:null,$f[0],$f[1],$f[2],$f[2]==='LIMIT'?'count':null]);
      $plans=[['STARTER','Starter',199900],['PROFESSIONAL','Professional',499900],['ENTERPRISE','Enterprise',999900]];$insPlan=$pdo->prepare('INSERT INTO plans(plan_guid,product_guid,plan_key,name,status,created_at,updated_at) VALUES(?,?,?,?,"ACTIVE",NOW(6),NOW(6)) ON DUPLICATE KEY UPDATE name=VALUES(name),updated_at=NOW(6)');$insPrice=$pdo->prepare('INSERT INTO prices(price_guid,plan_guid,currency,amount_minor,billing_interval,interval_count,status,created_at) VALUES(?,?,"INR",?,"MONTH",1,"ACTIVE",NOW(6))');
      foreach($plans as$pl){$pg=Uuid::v7();$insPlan->execute([Uuid::toBinary($pg),$productBin,$pl[0],$pl[1]]);$r=$pdo->prepare('SELECT plan_guid FROM plans WHERE product_guid=? AND plan_key=?');$r->execute([$productBin,$pl[0]]);$planBin=$r->fetchColumn();$cnt=$pdo->prepare('SELECT COUNT(*) FROM prices WHERE plan_guid=? AND currency="INR" AND billing_interval="MONTH"');$cnt->execute([$planBin]);if(!$cnt->fetchColumn())$insPrice->execute([Uuid::toBinary(Uuid::v7()),$planBin,$pl[2]]);}
      $limits=[
        'STARTER'=>['EPAPER.PUBLICATIONS'=>[1,1],'EPAPER.ADMIN_USERS'=>[1,2],'EPAPER.STORAGE_GB'=>[1,10],'EPAPER.OCR_SEARCH'=>[1,null],'EPAPER.SMART_ARTICLE'=>[0,null],'EPAPER.CLIPPING'=>[1,null],'EPAPER.OFFLINE'=>[0,null],'EPAPER.AD_FREE'=>[0,null],'PLATFORM.CUSTOM_DOMAINS'=>[1,1],'PLATFORM.API_ACCESS'=>[0,null],'PLATFORM.SSO'=>[0,null]],
        'PROFESSIONAL'=>['EPAPER.PUBLICATIONS'=>[1,5],'EPAPER.ADMIN_USERS'=>[1,10],'EPAPER.STORAGE_GB'=>[1,100],'EPAPER.OCR_SEARCH'=>[1,null],'EPAPER.SMART_ARTICLE'=>[1,null],'EPAPER.CLIPPING'=>[1,null],'EPAPER.OFFLINE'=>[1,null],'EPAPER.AD_FREE'=>[1,null],'PLATFORM.CUSTOM_DOMAINS'=>[1,3],'PLATFORM.API_ACCESS'=>[1,null],'PLATFORM.SSO'=>[0,null]],
        'ENTERPRISE'=>['EPAPER.PUBLICATIONS'=>[1,9999],'EPAPER.ADMIN_USERS'=>[1,9999],'EPAPER.STORAGE_GB'=>[1,10000],'EPAPER.OCR_SEARCH'=>[1,null],'EPAPER.SMART_ARTICLE'=>[1,null],'EPAPER.CLIPPING'=>[1,null],'EPAPER.OFFLINE'=>[1,null],'EPAPER.AD_FREE'=>[1,null],'PLATFORM.CUSTOM_DOMAINS'=>[1,9999],'PLATFORM.API_ACCESS'=>[1,null],'PLATFORM.SSO'=>[1,null]],
      ];
      $pf=$pdo->prepare('INSERT INTO plan_features(plan_guid,feature_guid,enabled,limit_value,config_json) VALUES(?,?,?,?,NULL) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled),limit_value=VALUES(limit_value)');
      foreach($limits as$planKey=>$defs){$q=$pdo->prepare('SELECT plan_guid FROM plans WHERE product_guid=? AND plan_key=?');$q->execute([$productBin,$planKey]);$planBin=$q->fetchColumn();foreach($defs as$featureKey=>$def){$fq=$pdo->prepare('SELECT feature_guid FROM features WHERE feature_key=?');$fq->execute([$featureKey]);if($fg=$fq->fetchColumn())$pf->execute([$planBin,$fg,$def[0],$def[1]]);}}
      $permissionKeys=['platform.organisations.manage','platform.products.manage','platform.domains.manage','platform.billing.manage','platform.operations.view','platform.support.impersonate','tenant.editions.manage','tenant.publications.manage','tenant.branding.manage','tenant.users.manage','tenant.analytics.view'];$pi=$pdo->prepare('INSERT INTO permissions(permission_guid,permission_key,description,created_at) VALUES(?,?,?,NOW(6)) ON DUPLICATE KEY UPDATE description=VALUES(description)');foreach($permissionKeys as$pk)$pi->execute([Uuid::toBinary(Uuid::v7()),$pk,$pk]);
      $pdo->commit();
      if(file_put_contents($configFile,"<?php\nreturn ".var_export($cfg,true).";\n",LOCK_EX)===false)throw new RuntimeException('Could not save private configuration after database initialization.');
      chmod($configFile,0640);
      file_put_contents($lock,json_encode(['installed_at'=>gmdate('c'),'version'=>'1.0.1','admin_email'=>$adminEmail],JSON_PRETTY_PRINT),LOCK_EX);$success=true;
    }catch(Throwable$e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$errors[]=($e instanceof RuntimeException && !($e instanceof PDOException))
        ?$e->getMessage()
        :'Installation could not complete. Check the private server error log before retrying on a new empty database.';}
  }
}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Install Digiti Platform</title><style>body{font-family:system-ui,sans-serif;background:#f5f5f7;color:#1d1d1f;margin:0}.wrap{max-width:900px;margin:40px auto;padding:24px}.card{background:#fff;border:1px solid #ddd;border-radius:18px;padding:24px;margin:16px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{display:grid;gap:6px;font-size:14px}input,select{padding:11px;border:1px solid #ccc;border-radius:10px}button{padding:12px 18px;border:0;border-radius:10px;background:#1d1d1f;color:#fff}.ok{color:#137333}.bad{color:#b3261e}.error{background:#fff1f0;padding:12px;border-radius:10px}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><div class="wrap"><h1>Digiti Platform v1.0.1</h1><p>Cloudways / PHP / MariaDB / Redis installation.</p><?php if($success):?><div class="card"><h2 class="ok">Installation complete</h2><p>Platform database and foundation modules were installed and the installer is now locked.</p><p><a href="/login">Open Platform Admin</a></p></div><?php else:?><?php foreach($errors as$e):?><div class="error"><?=htmlspecialchars($e)?></div><?php endforeach;?><div class="card"><h2>Requirements</h2><?php foreach($requirements as$n=>$ok):?><p class="<?=$ok?'ok':'bad'?>"><?=$ok?'PASS':'FAIL'?> — <?=htmlspecialchars($n)?></p><?php endforeach;?></div><form method="post"><div class="card"><h2>Application</h2><div class="grid"><label>Platform URL<input name="app_url" value="https://platform.digiti.in" required></label><label>Auth URL<input name="auth_url" value="https://auth.digiti.in" required></label><label>ePaper SaaS URL<input name="epaper_url" value="https://epaper.digiti.in" required></label><label>ePaper SaaS Auth Callback<input name="epaper_callback" value="https://epaper.digiti.in/auth/callback" required></label><label>Customer domain CNAME target<input name="domains_target" value="domains.digiti.in" required></label><label>Environment<select name="env"><option>production</option><option>staging</option><option>development</option></select></label><label>Timezone<input name="timezone" value="Asia/Kolkata"></label><label>Mail From<input name="mail_from" value="no-reply@digiti.in"></label></div></div><div class="card"><h2>MariaDB</h2><div class="grid"><label>Host<input name="db_host" value="127.0.0.1"></label><label>Port<input name="db_port" value="3306"></label><label>Database<input name="db_name" required></label><label>User<input name="db_user" required></label><label>Password<input type="password" name="db_pass"></label></div></div><div class="card"><h2>Redis</h2><label><input type="checkbox" name="redis_enabled" value="1" checked> Enable Redis</label><div class="grid"><label>Host<input name="redis_host" value="127.0.0.1"></label><label>Port<input name="redis_port" value="6379"></label><label>Username<input name="redis_username"></label><label>Password<input type="password" name="redis_password"></label><label>Database<input name="redis_database" value="0"></label></div></div><div class="card"><h2>Platform Administrator</h2><div class="grid"><label>Name<input name="admin_name" required></label><label>Email<input type="email" name="admin_email" required></label><label>Password<input type="password" name="admin_pass" minlength="12" required></label></div></div><label>Type NEW EMPTY DATABASE<input name="confirm_new_database" required autocomplete="off" placeholder="NEW EMPTY DATABASE"></label><button>Install Platform</button></form><?php endif;?></div></body></html>
